  ($q$adv-289$q$, $q$math$q$, $q$Advanced Math$q$, $q$Exponential equations$q$, 1, null, $q$If 7<sup>2x−1</sup> = 49, what is the value of x?$q$, $q$["1.5","2","0.5","3"]$q$::jsonb, 0, $q$49 = 7², so 2x − 1 = 2 → x = 1.5.$q$, null),
  ($q$adv-290$q$, $q$math$q$, $q$Advanced Math$q$, $q$Exponential equations$q$, 2, null, $q$If 16<sup>x</sup> = 4<sup>x+3</sup>, what is the value of x?$q$, $q$["3","6","1","9"]$q$::jsonb, 0, $q$Write both sides with base 4: 16<sup>x</sup> = 4<sup>2x</sup>. Setting exponents equal: 2x = x + 3 → x = 3.$q$, null),
  ($q$adv-291$q$, $q$math$q$, $q$Advanced Math$q$, $q$Exponential equations$q$, 2, null, $q$If 25<sup>x−1</sup> = 5<sup>x+3</sup>, what is the value of x?$q$, $q$["5","1","−5","10"]$q$::jsonb, 0, $q$Write both sides with base 5: 25<sup>x−1</sup> = 5<sup>2x−2</sup>. Setting exponents equal: 2x − 2 = x + 3 → x = 5.$q$, null),
  ($q$adv-292$q$, $q$math$q$, $q$Advanced Math$q$, $q$Exponential equations$q$, 2, null, $q$If 3<sup>3x + 6</sup> = 27<sup>3x + 4</sup>, what is the value of x?$q$, $q$["−3","1","0","−1"]$q$::jsonb, 3, $q$Both sides can be written with base 3: 3 = 3<sup>1</sup> and 27 = 3<sup>3</sup>. The equation becomes 3<sup>1(3x + 6)</sup> = 3<sup>3(3x + 4)</sup>, so 1(3x + 6) = 3(3x + 4). Solving this linear equation gives x = −1.$q$, null),
  ($q$adv-293$q$, $q$math$q$, $q$Advanced Math$q$, $q$Exponential equations$q$, 2, null, $q$If 5<sup>x + 1</sup> = 25<sup>x − 3</sup>, what is the value of x?$q$, $q$["7","5","8","−7"]$q$::jsonb, 0, $q$Both sides can be written with base 5: 5 = 5<sup>1</sup> and 25 = 5<sup>2</sup>. The equation becomes 5<sup>1(x + 1)</sup> = 5<sup>2(x − 3)</sup>, so 1(x + 1) = 2(x − 3). Solving this linear equation gives x = 7.$q$, null),
  ($q$adv-294$q$, $q$math$q$, $q$Advanced Math$q$, $q$Exponential equations$q$, 2, null, $q$If 2<sup>x</sup> · 2<sup>x+1</sup> = 32, what is the value of x?$q$, $q$["2","1.5","3","2.5"]$q$::jsonb, 0, $q$2<sup>x</sup> · 2<sup>x+1</sup> = 2<sup>2x+1</sup> = 32 = 2<sup>5</sup>, so 2x + 1 = 5 → x = 2.$q$, null),
  ($q$adv-295$q$, $q$math$q$, $q$Advanced Math$q$, $q$Exponents$q$, 1, null, $q$What is the value of 8² · 8⁻¹?$q$, $q$["8","64","1/8","16"]$q$::jsonb, 0, $q$Add the exponents: 8<sup>2 + (−1)</sup> = 8<sup>1</sup> = 8.$q$, null),
