  ($q$adv-298$q$, $q$math$q$, $q$Advanced Math$q$, $q$Exponents$q$, 1, null, $q$What is the value of 7⁻¹ · 7³?$q$, $q$["49","7","1/7","343"]$q$::jsonb, 0, $q$Add the exponents: 7<sup>−1+3</sup> = 7² = 49.$q$, null),
  ($q$adv-299$q$, $q$math$q$, $q$Advanced Math$q$, $q$Exponents$q$, 1, null, $q$What is the value of (2³ · 2⁴) / 2⁵?$q$, $q$["4","2","8","16"]$q$::jsonb, 0, $q$Using exponent rules: 2<sup>3+4−5</sup> = 2² = 4.$q$, null),
  ($q$adv-300$q$, $q$math$q$, $q$Advanced Math$q$, $q$Exponents$q$, 1, null, $q$What is the value of 5⁻² · 5⁴?$q$, $q$["25","5","1/25","125"]$q$::jsonb, 0, $q$Add the exponents: 5<sup>−2+4</sup> = 5² = 25.$q$, null),
  ($q$adv-301$q$, $q$math$q$, $q$Advanced Math$q$, $q$Exponents$q$, 2, null, $q$What is the value of (4<sup>1</sup> · 4<sup>−1</sup>) / 4<sup>−1</sup>?$q$, $q$["0.25","1","16","4"]$q$::jsonb, 3, $q$Combine exponents: 1 − (1) − (−1) = 1. So the expression equals 4<sup>1</sup> = 4.$q$, null),
  ($q$adv-302$q$, $q$math$q$, $q$Advanced Math$q$, $q$Exponents$q$, 2, null, $q$Which expression is equivalent to (x<sup>1</sup> · x<sup>1/2</sup>) / x<sup>2/3</sup>, for x > 0?$q$, $q$["x<sup>5/6</sup>","x<sup>13/6</sup>","x<sup>−1/6</sup>","x<sup>−5/6</sup>"]$q$::jsonb, 0, $q$Using exponent rules, multiplying adds exponents and dividing subtracts them: 1 + 1/2 − 2/3 = 5/6. So the expression simplifies to x<sup>5/6</sup>.$q$, null),
  ($q$adv-303$q$, $q$math$q$, $q$Advanced Math$q$, $q$Exponents$q$, 1, null, $q$What is the value of (3³)² / (3²)²?$q$, $q$["9","3","27","81"]$q$::jsonb, 0, $q$(3³)² = 3⁶ = 729, and (3²)² = 3⁴ = 81. Then 729 / 81 = 3<sup>6−4</sup> = 3² = 9.$q$, null),
