  ($q$adv-349$q$, $q$math$q$, $q$Advanced Math$q$, $q$Exponential equations$q$, 1, null, $q$If 4<sup>x</sup> = 256, what is the value of x?$q$, $q$["4","8","2","64"]$q$::jsonb, 0, $q$256 = 4<sup>4</sup>, so 4<sup>x</sup> = 4<sup>4</sup> means x = 4.$q$, null),
  ($q$adv-350$q$, $q$math$q$, $q$Advanced Math$q$, $q$Exponential functions$q$, 2, null, $q$A bacteria culture is modeled by B(t) = 200(2)<sup>t</sup>, where t is measured in hours. What is the population, to the nearest whole number, after 4 hours?$q$, $q$["3200","1600","800","6400"]$q$::jsonb, 0, $q$200(2)<sup>4</sup> = 200(16) = 3200.$q$, null),
