  ($q$adv-354$q$, $q$math$q$, $q$Advanced Math$q$, $q$Function composition$q$, 1, null, $q$If f(x) = x + 5 and g(x) = 2x, what is the value of f(g(3))?$q$, $q$["11","16","13","10"]$q$::jsonb, 0, $q$g(3) = 2(3) = 6, and f(6) = 6 + 5 = 11.$q$, null),
  ($q$adv-355$q$, $q$math$q$, $q$Advanced Math$q$, $q$Equivalent expressions$q$, 1, null, $q$Which expression is equivalent to (5x³)(2x⁴)?$q$, $q$["10x<sup>7</sup>","7x<sup>7</sup>","10x<sup>12</sup>","7x<sup>12</sup>"]$q$::jsonb, 0, $q$Multiply coefficients and add exponents: 5·2 = 10, and x³·x⁴ = x<sup>7</sup>, giving 10x<sup>7</sup>.$q$, null),
  ($q$adv-356$q$, $q$math$q$, $q$Advanced Math$q$, $q$Quadratic equations$q$, 2, null, $q$If 3x² − 7x − 6 = 0, what is the sum of the solutions?$q$, $q$["7/3","−7/3","2","−2"]$q$::jsonb, 0, $q$3x² − 7x − 6 = (3x + 2)(x − 3) = 0, so x = −2/3 or x = 3. Their sum is −2/3 + 3 = 7/3.$q$, null),
  ($q$adv-357$q$, $q$math$q$, $q$Advanced Math$q$, $q$Quadratic inequalities$q$, 2, null, $q$For what values of x is the inequality x² − 2x − 15 ≤ 0 true?$q$, $q$["−3 ≤ x ≤ 5","−5 ≤ x ≤ 3","x ≤ −3 or x ≥ 5","x ≤ −5 or x ≥ 3"]$q$::jsonb, 0, $q$x² − 2x − 15 = (x − 5)(x + 3), which is ≤ 0 between the roots, so −3 ≤ x ≤ 5.$q$, null),
  ($q$adv-358$q$, $q$math$q$, $q$Advanced Math$q$, $q$Exponential equations$q$, 1, null, $q$If 3<sup>2x−1</sup> = 27, what is the value of x?$q$, $q$["2","1","4","3/2"]$q$::jsonb, 0, $q$27 = 3³, so 2x − 1 = 3 → 2x = 4 → x = 2.$q$, null),
  ($q$adv-359$q$, $q$math$q$, $q$Advanced Math$q$, $q$Exponential functions$q$, 1, null, $q$The function f(x) = 3(5)<sup>x</sup> represents exponential growth. What is the value of f(2)?$q$, $q$["75","25","15","125"]$q$::jsonb, 0, $q$f(2) = 3(5)² = 3(25) = 75.$q$, null),
